'use client'

// app/page.js - VERSION OPTIMISÉE

import { useState, useMemo, useCallback, lazy, Suspense } from 'react'
import { useAuth } from '@/hooks/useAuth'
import { useLieux } from '@/hooks/useLieux'
import { useVilles } from '@/hooks/useVilles'
import { useCategories } from '@/hooks/useCategories'
import { useToast } from '@/contexts/ToastContext'
import { MESSAGES } from '@/lib/constants'
import { filterLieux } from '@/utils/helpers'

// Composants statiques
import MainMenu from '@/components/MainMenu'
import ModalLogin from '@/components/ModalLogin'
import BarreAdmin from '@/components/BarreAdmin'
import FiltresLieux from '@/components/FiltresLieux'
import TableauLieux from '@/components/TableauLieux'
import ContributionsAdmin from '@/components/ContributionsAdmin'

// Lazy loading des composants lourds
const SidebarLieu = lazy(() => import('@/components/SidebarLieu'))
const SidebarEditLieu = lazy(() => import('@/components/SidebarEditLieu'))

// Composant de fallback pour le chargement
function SidebarSkeleton() {
  return (
    <div className="fixed right-0 top-0 h-full w-[90vw] max-w-[500px] bg-white shadow-2xl z-50 p-6 animate-pulse">
      <div className="h-8 bg-gray-200 rounded w-3/4 mb-6"></div>
      <div className="space-y-4">
        <div className="h-4 bg-gray-200 rounded"></div>
        <div className="h-4 bg-gray-200 rounded w-5/6"></div>
        <div className="h-4 bg-gray-200 rounded w-4/6"></div>
      </div>
    </div>
  )
}

export default function Home() {
  // 🔐 Hooks de données
  const auth = useAuth()
  const lieuxData = useLieux()
  const villesData = useVilles()
  const categoriesData = useCategories()
  const toast = useToast()

  // 🎨 États UI locaux
  const [selectedLieu, setSelectedLieu] = useState(null)
  const [lieuToEdit, setLieuToEdit] = useState(null)
  const [showEditSidebar, setShowEditSidebar] = useState(false)
  const [filtresActifs, setFiltresActifs] = useState({ types: [], villes: [] })

  // 🎯 Filtrage mémoïsé des lieux (évite recalcul à chaque render)
  const lieuxFiltres = useMemo(
    () => filterLieux(lieuxData.lieux, filtresActifs),
    [lieuxData.lieux, filtresActifs]
  )

  // 📝 Handlers stabilisés avec useCallback
  const handleEdit = useCallback((lieu) => {
    setLieuToEdit(lieu)
    setShowEditSidebar(true)
  }, [])

  const handleAdd = useCallback(() => {
    setLieuToEdit(null)
    setShowEditSidebar(true)
  }, [])

  const handleDelete = useCallback(async (id, ville) => {
    if (!confirm(MESSAGES.CONFIRMER_SUPPRESSION)) return

    try {
      await lieuxData.supprimerLieu(id)

      // Vérifier si la ville a encore des lieux
      const lieuxRestants = lieuxData.lieux.filter(l => l.ville === ville && l.id !== id)
      if (lieuxRestants.length === 0) {
        await villesData.supprimerVille(ville)
      }

      toast.success(MESSAGES.SUCCESS_SUPPRESSION)
    } catch (error) {
      toast.error(`Erreur : ${error.message}`)
    }
  }, [lieuxData, villesData, toast])

  const handleCloseSidebar = useCallback(() => {
    setShowEditSidebar(false)
    setLieuToEdit(null)
  }, [])

  const handleLieuClick = useCallback((lieu) => {
    setSelectedLieu(lieu)
  }, [])

  const handleCloseLieuSidebar = useCallback(() => {
    setSelectedLieu(null)
  }, [])

  // ⏳ Loading state
  if (auth.loading || lieuxData.loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-gray-200 border-t-blue-600 mb-4"></div>
          <p className="text-xl text-gray-600">Chargement...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      <div className="w-[95%] max-w-[95rem] mx-auto">
        
        {/* Header */}
        <header className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex justify-between items-start mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-800">Hexa Index</h1>
              <h2 className="text-xl font-bold text-gray-800">
                Index de ressources pour design·euse·r·s graphiques
              </h2>
              {auth.isAdmin && (
                <p className="text-sm text-green-600 mt-1" role="status">
                  Mode administrateur
                </p>
              )}
            </div>

            {/* Boutons admin */}
            <BarreAdmin 
              auth={auth} 
              lieuxData={lieuxData}
              villesData={villesData}
              categoriesData={categoriesData}
              onAddClick={handleAdd}
            />
          </div>

          <nav className="mt-4" aria-label="Navigation principale">
            <MainMenu />
          </nav>
        </header>

        {/* Contributions admin (encadré orange) */}
        {auth.isAdmin && <ContributionsAdmin />}

        {/* Filtres */}
        <FiltresLieux 
          categories={categoriesData.categories}
          villes={villesData.villes}
          filtresActifs={filtresActifs}
          setFiltresActifs={setFiltresActifs}
        />

        {/* Tableau des lieux */}
        <TableauLieux 
          lieux={lieuxFiltres}
          onLieuClick={handleLieuClick}
          isAdmin={auth.isAdmin}
          onEdit={handleEdit}
          onDelete={handleDelete}
        />

        {/* Modals & Sidebars avec lazy loading */}
        <ModalLogin auth={auth} />
        
        <Suspense fallback={<SidebarSkeleton />}>
          {selectedLieu && (
            <SidebarLieu 
              lieu={selectedLieu}
              onClose={handleCloseLieuSidebar}
              isAdmin={auth.isAdmin}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          )}
        </Suspense>
        
        <Suspense fallback={<SidebarSkeleton />}>
          {showEditSidebar && (
            <SidebarEditLieu 
              show={showEditSidebar}
              onClose={handleCloseSidebar}
              lieuToEdit={lieuToEdit}
              lieuxData={lieuxData}
              villesData={villesData}
              categoriesData={categoriesData}
            />
          )}
        </Suspense>
      </div>
    </div>
  )
}